# Tips for tips.html. Plain words for a first visit. Facts trace to the notes.
# Tips 16, 18, 19, 20, 21, 22, 27, 32 and 35 were cut: too tied to our own desk.
# Tip 24 is merged into page-loads. No example is invented where none was confirmed.
M='Milliways'; X='Moxie'; T='Metis'; G='Grok'
C='tips/img/'
TOPICS=['Store setup','Product photos','Print-on-demand','Your website','Posting on X','Working with bots']
TIPS=[
# Store setup
dict(id='contact-details',topic='Store setup',bot=X,lay='beside',title='Keep your home address off your store',
 do='Put a business email, phone and address in Shopify under Settings, then General, then Store contact details. Shopify copies those details onto your public privacy, refund and contact pages.',
 why='Those pages are public. Shopify’s help says to use business details, especially if you run the shop from home. For example, use a business email instead of the address where you live.',
 links=[('Shopify Help','https://help.shopify.com/en/manual/checkout-settings/refund-privacy-tos')]),
dict(id='sort-by-design',topic='Store setup',bot=M,lay='above',title='Sort by design, each tee next to its tank',
 do='Sort your main collection by hand and group it by design. A tank is a sleeveless shirt. For example, put each tee right before the tank top that uses the same art.',
 why='Our Wear page was sorted by best sellers, so a tee and the tank with the same design sat far apart. A hand-picked order fixed it on Oct 15, with 41 changes logged.',
 links=[('Shopify Help','https://help.shopify.com/en/manual/products/collections/collection-layout'),
        ('See the build','builds/collection-arranger.html')]),
dict(id='custom-out',topic='Store setup',bot=M,lay='right',title='Keep custom orders out of your main shelves',
 do='Use Shopify’s automatic collection rules to keep custom-made and service listings out of your main collections, and give them their own menu link. An automatic rule fills a collection for you, for example “product type is not Custom.”',
 why='Ours were showing up between ready-to-buy shirts.',
 img=[C+'compare-custom-cipher-how-it-works.jpg'],
 cap='A custom listing that had been sitting among ready-to-buy shirts.',
 links=[('Shopify Help','https://help.shopify.com/en/manual/products/collections/smart-collections')]),
dict(id='hidden-by-link',topic='Store setup',bot=M,lay='beside',title='Hidden pages only open by direct link',
 do='A hidden page or product will not show in menus, collections or search. If buyers should find it on their own, add a link. For example, add a menu link for a product you still want people to open.',
 why='Hiding is right for a private page. It is a problem only when you meant the page to be found.',
 links=[('Shopify Help','https://help.shopify.com/en/manual/online-store/storefront-search/managing-searchability')]),
dict(id='theme-switch',topic='Store setup',bot=M,lay='above',title='Before a new store design goes live, compare every page',
 do='Put the old and new design side by side, page by page, on a desktop and a phone, before you publish. For example, check the footer, the strip of links at the bottom of the page, and any page where a buyer has to type something.',
 why='Our check of 12 pages, before a switch to Shopify’s Horizon theme, found the custom-word shirt page missing (buyers could have ordered without typing their word), a footer stripped of links, contact details and payment icons, an added “Powered by Shopify” line, and new screen reader errors. All of it was fixed before any buyer saw it.'),
dict(id='alt-text',topic='Store setup',bot=M,lay='left',title='Write real alt text for every product photo',
 do='Alt text is the description a screen reader reads aloud for someone who cannot see the photo. Write what the photo shows. For example, “Myth Engine Tee, t-shirt in black, front view,” not “Product mockup.”',
 why='Ours said “Product mockup” on photo after photo. 60 were rewritten. After that, the accessibility check was clean apart from 1 label issue.',
 img=[C+'compare-a11y-product-desktop.jpg',C+'compare-a11y-home-mobile.jpg'],
 cap='Product photos after the alt text was rewritten.',
 links=[('Shopify Help','https://help.shopify.com/en/manual/products/product-media/add-alt-text')]),
# Product photos
dict(id='real-print-file',topic='Product photos',bot=M,lay='stack',title='Generated model photos redraw your print. Put the real file back on.',
 do='A generated model photo is a picture a tool drew of someone wearing the shirt. Check it against your real print file. Where the art is wrong, place the real print file onto the photo.',
 why='Of 73 apparel photos checked, the generated shots had redrawn the art: cut-off headlines, a line faded by a gradient, and one line that came out twice on the shirt. 17 fixed photos went up (13 replacements, 4 new), and the old ones were taken off, not deleted.',
 img=[C+'compare-mockup-dark-matter-racerback-tank-1.jpg',C+'compare-mockup-myth-engine-racerback-tank-1-smear.jpg'],
 cap='Generated model shots, with the real print file placed back on.',
 duo=True),
dict(id='same-model',topic='Product photos',bot=M,lay='left',title='Use the same model on the front and the back',
 do='If you make model photos, make the back view from the front shot, so it is the same person, then add the real back print.',
 why='Three of our listings showed one person on the front and someone else on the back: the Big Bang tank, the Big Bang tee and the Read the Cipher hoodie.',
 img=[C+'compare-mockup-read-the-cipher-hoodie-3.jpg'],
 cap='A hoodie whose front and back needed the same person.'),
dict(id='vary-models',topic='Product photos',bot=M,lay='right',title='Vary the models across listings',
 do='Change the models from listing to listing, and keep each listing to one model. For example, a different person on the next shirt, and the same person on that shirt’s front and back.',
 why='If every listing shows the same kind of person, the shop looks narrow and less welcoming.',
 img=[C+'compare-mockup-big-bang-racerback-tank-1-man.jpg',C+'compare-mockup-charismata-racerback-tank-1-tri.jpg'],
 cap='Different listings can show different people. Each listing stays with one.'),
dict(id='drop-white',topic='Product photos',bot=M,lay='beside',title='Drop the plain white mockups',
 do='A mockup here means the flat sample photo a print partner makes, often on plain white. Take those down, but keep any photo that is the only picture for a color until a replacement is up.',
 why='Our white Light Cone shirt’s only photos were white mockups, so the new dark shots went up before the old ones came off. On Oct 15 the log showed 35 photos taken off and 160 options pointed at the new photos, with nothing deleted.'),
dict(id='pdf-preview',topic='Product photos',bot=M,lay='left',title='Make digital product previews bright, and say buyers can type into them',
 do='Check your digital product preview at the size it appears in the shop. If buyers can type into the file, say so. “Fillable” means the buyer can type into the fields.',
 why='Ours showed four dark pages that looked like black cards. At listing size the text was about 2 pixels tall, and the cover’s brightness was 22 out of 255. Nothing said the PDF has 787 fields buyers can type into. Show filled-in pages, and say it is fillable.',
 img=[C+'compare-inner-house-preview.jpg'],
 cap='A brighter preview, so the pages are readable at listing size.'),
# Print-on-demand
dict(id='sold-out',topic='Print-on-demand',bot=M,lay='above',comic=True,title='Your print partner can make made-to-order items look sold out',
 do='Print-on-demand means the shirt is printed when someone orders it. It is not sitting in a stock room. After every sync, check that inventory tracking is still off for those items. Printful advises against editing inventory by hand.',
 why='Each Printful sync switched our Shopify stock tracking back on, so shirts printed when you order showed as sold out. That part rests on our own build. A Grok Bot switches tracking off every morning at 6:41 AM CT. It does not log how many fixes it makes.',
 links=[('Printful: product stock sync','https://help.printful.com/hc/en-us/articles/50263482677009-What-is-product-stock-sync-and-how-does-it-affect-my-store'),
        ('See the build','builds/stock-tracking-guard.html')]),
dict(id='small-text',topic='Print-on-demand',bot=M,lay='beside',title='Size small text up, and keep one print file per design',
 do='Make tiny lines bigger than you think. For example, keep one print file per design and let the print partner scale it, instead of a separate file for every size.',
 why='Our line “* = 69” printed at about 6.5 mm. It was readable on a shirt and a smudge in the photos. At about 12 mm, 1.8 times the size, it works. Those files are live on 4 products.'),
dict(id='neck-label',topic='Print-on-demand',bot=M,lay='above',title='Price add-ons before you offer them',
 do='Look up what each add-on costs per item before it goes on your product page. For example, open the price page and read the line for the exact add-on you mean, not the one beside it.',
 why='We quoted about $2.49 for a printed inside label. That figure is Printful’s outside-label price. The inside label is about $0.99. Check the price page before you quote an add-on.',
 links=[('Printful pricing','https://www.printful.com/pricing')]),
dict(id='freelancer-ranges',topic='Print-on-demand',bot=M,lay='beside',title='Price your services from real market ranges',
 do='Before you price design work, check what freelancers charge right now on more than one site. A freelancer is someone hired for one job.',
 why='Upwork blocked our bot, so we used Fiverr and 99designs. Custom tee designs ran about $9 to $25 at the low end, about $46 to $99 as a typical price, and about $299 to $799 for a premium contest.'),
# Your website
dict(id='checkable',topic='Your website',bot=X,lay='above',title='Make every fact checkable',
 do='Name who said each quote and where, trace every number to a source, and cut what you cannot check.',
 why='A reader should be able to tell a checked fact from a guess. For example, if you quote someone, write their name and the page you took the words from. If you print a number, write where it came from. If you cannot check it, leave it out.'),
dict(id='page-loads',topic='Your website',bot=T,lay='stack',title='A page can load and still be broken',
 do='Check what a page shows, not only that it loads. A design file, also called a stylesheet, sets the colors and the type. A script file adds behavior. Test each one twice, a few minutes apart. If you use an automatic check, make it fail when a page has no design file linked at all.',
 why='Our own homepage once came up as plain text because its design file was never uploaded. The file returned “not found” on two checks about two minutes apart. Our first check only asked “does this file exist?” and would have passed a page with no styling.',
 img=[C+'pr10-live-home-1440.jpg'],
 cap='A homepage that loaded with its design file missing.'),
dict(id='crops',topic='Your website',bot=T,lay='stack',title='Check photo crops at real sizes',
 do='Look at photo crops on a phone and on a big screen. A crop is the part of the photo you choose to show. For example, also check that blocks share the same left and right edges.',
 why='On our team strip, square crops with the face position set to “100% center” pushed half of two faces out of the frame. “50% center” fixed it.',
 img=[C+'pr9-strip-before.jpg',C+'pr9-strip-after.jpg'],
 cap='The team strip before and after the crop center was moved.',
 duo=True),
dict(id='live-render',topic='Your website',bot=T,lay='beside',title='Only the live page counts',
 do='After every change, open the published page and look. For example, open it on a phone and on a desktop. Code that looks right is not proof.',
 why='A fix we reviewed looked right in the code, but nobody had built it yet, so we held it until it worked live.'),
dict(id='contact',topic='Your website',bot=X,lay='above',title='Put a contact line on every page',
 do='Put a contact line on every page. For example, an email address a visitor can see without hunting for it.',
 why='When we checked homepages only, 58 of 83 sites had a contact address and 25 did not. Those 25 were 14 kids’ sites and 11 other sites.'),
dict(id='readable-text',topic='Your website',bot=X,lay='left',title='Give text enough contrast',
 do='WCAG, the Web Content Accessibility Guidelines, asks for enough contrast so people can read the words. Contrast is the difference between the text and what sits behind it. For example, check a pale color on a bright photo, not only black on white.',
 why='Our gold captions over video were so hard to read that the owner said “I can’t read any of the font with the yellow.” We moved those captions to white or ivory, about 8% of the screen height, on a soft dark box, and kept gold for decoration.',
 img=[C+'canva-threshold-before-fix.jpg',C+'canva-threshold-text-fixed-preview.jpg'],
 cap='Captions before and after they had enough contrast.',
 links=[('WCAG: contrast minimum','https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html')]),
dict(id='install-icons',topic='Your website',bot=T,lay='beside',title='Give each site its own icon if people save it to their phone',
 do='If people can save your site to a phone’s home screen, the grid of icons on the phone, give the site its own icon. Check how the art looks, not only the file size.',
 why='In our test of three sites the code passed, but two icons had to be redrawn.'),
# Posting on X
dict(id='share-cards',topic='Posting on X',bot=T,lay='right',title='Give each page its own share card',
 do='A share card is the preview picture X shows when someone posts your link. Set a large one for every page you want shared. For example, an image about 1200 by 630.',
 why='Before the fix, every comic shared on X showed the same site picture. Each comic now has its own card.',
 img=[C+'pr14-share-cards.jpg'],
 cap='Share cards, so each page can show its own preview.'),
dict(id='link-test',topic='Posting on X',bot=X,lay='above',title='Test where your link goes before you settle on a habit',
 do='Try your link in the post, in the first reply, and in both, for two weeks, before you decide.',
 why='Our first two test days had 51 and 23 views and 0 link clicks. One day ran wrong (Oct 14), so it gets a make-up day. Zero clicks that early tells you nothing yet.'),
dict(id='label-generated',topic='Posting on X',bot=G,lay='beside',title='Label generated images on X',
 do='When a post uses a generated image or video and you send it through X’s API, the way a program posts instead of typing into the app, set made_with_ai to true in the request body. That is the request for POST /2/tweets. It turns on the Made with AI label. For example, the body includes "made_with_ai": true.',
 why='We have labeled every image and video post since Oct 11.',
 links=[('Grok on X','https://x.com/grok/status/2109056799265464528')]),
dict(id='say-who-made',topic='Posting on X',bot=X,lay='above',title='Say what a bot made',
 do='Mark automated accounts and name the tools in your credits. For example, write “made with Grok Bot.” The questions and the direction stay human.',
 why='Readers deserve to know who, or what, made a piece.'),
# Working with bots
dict(id='detach-log',topic='Working with bots',bot=M,lay='beside',title='Take things off instead of deleting, and log every change',
 do='Have your bot take items off the page instead of deleting them, write down each change with the time, and wait for your OK before uploading. For example, remove a photo from the product and keep the file, so you can put it back.',
 why='A change you can undo is safer than a delete, and nothing should go up until you say yes.'),
dict(id='cost-summaries',topic='Working with bots',bot=X,lay='above',title='Check cost summaries against the full log',
 do='When a bot reports a total, open the full log once. For example, if the summary skips a kind of charge, add those lines before you trust the total.',
 why='One of our spend summaries left out the animation clips and said $12.70. The real total was $41.79.',
 links=[('See the build','builds/shorts-video-pipeline.html')]),
dict(id='research-gaps',topic='Working with bots',bot=X,lay='beside',title='Ask research bots for a could-not-read list',
 do='A research bot reads public pages and writes a report. Ask for a “could not read” list with every report.',
 why='Tesla’s shop blocked our bot, Patagonia showed a waiting page, and Threadless showed nothing readable. Because the bot wrote them down, we knew what was missing.',
 links=[('See the build','builds/merch-design-research.html')]),
dict(id='gate',topic='Working with bots',bot=T,lay='above',title='Review every change with pass, fix or hold',
 do='Give each change one verdict: pass (ship it), fix (one named problem) or hold (not enough proof yet). For example, a hold note says what proof would clear it.',
 why='“Looks good” does not tell you what to do next. One of our changes got hold because nobody had built it, and the note said what would clear it.'),
dict(id='freeze-passed',topic='Working with bots',bot=X,lay='beside',title='Keep what passed, fix only what failed',
 do='Check first, fix only the part that failed, and leave the rest alone. For example, replace the one photo that is wrong and leave the others.',
 why='Fixing parts that already passed opens them up again.'),
dict(id='one-change',topic='Working with bots',bot=T,lay='above',title='One change at a time',
 do='Keep each change small and start it from your latest live version. For example, finish one change and let it go live before you start the next.',
 why='We stacked one change on another. The site moved on, and the stack could not go live until we rebuilt it.'),
dict(id='plain-words',topic='Working with bots',bot=T,lay='beside',title='Set a house style for words',
 do='A house style, sometimes called a brand guideline, is a short list of how you write and how the pages look, so every page sounds like the same shop. Write the list down and check each change against it. These are examples, not orders: curly quotes and apostrophes, no long dashes, and text big enough to read. A starter list can be 2 fonts, 3 colors, a minimum text size, how you write dates and numbers, and your voice in 3 words.',
 why='Without a list, each new page invents its own rules. Even with the rule written down, a check on Oct 13 still found long dashes on 6 sites.'),
]
